SELECT id 
FROM w 
WHERE c4 LIKE '%vic grassi%';

SELECT id 
FROM w 
WHERE c4_month = 2;

SELECT id 
FROM w 
WHERE c10_number > 25;

SELECT COUNT(*)
FROM w 
JOIN t_c4_address ON w.c4 = t_c4_address.c4_address;

SELECT COUNT(*) 
FROM w 
WHERE c2 = 'tiger woods';

SELECT COUNT(*) 
FROM w 
WHERE c1 = 'conservative';

SELECT COUNT(*) AS record_count 
FROM w 
WHERE c3_length = 2;

SELECT COUNT(*) 
FROM w 
WHERE c2_first_number > c4_number;

SELECT COUNT(*) 
FROM w 
WHERE c3_number = 9;

SELECT COUNT(*) 
FROM w 
WHERE c4_number > 1000;

SELECT COUNT(*) 
FROM w 
WHERE c2_number > 100000;

SELECT COUNT(*) AS count 
FROM w 
WHERE c7_number > 50;

SELECT AVG(c4_number) AS avg_c4_number 
FROM w 
WHERE agg = 0;

SELECT DISTINCT c2 
FROM w 
WHERE agg = 0;

SELECT COUNT(*) 
FROM w 
WHERE c2_length = 1;

SELECT AVG(c3_number) 
FROM w
WHERE c5_number > 70;

SELECT AVG(c3_number) 
FROM w 
WHERE c5_number > 100;

SELECT AVG(c3_number) 
FROM w 
WHERE c5_number > 70;

SELECT c1, AVG(c3_number) AS avg_c3_number 
FROM w 
GROUP BY c1;

SELECT SUM(c2_number) 
FROM w 
WHERE c4_number < 0 AND agg = 0;

SELECT SUM(c1_number) AS total_c1_number 
FROM w 
WHERE c2_day = 17 AND agg = 0;

SELECT SUM(c7_number) 
FROM w 
WHERE c6 = 'metropolitan stadium';

SELECT SUM(c4_number) AS total_gold_medals 
FROM w 
WHERE c2 LIKE '%united states (usa)%' AND c3 BETWEEN '2006-2014' AND '2014';

SELECT SUM(c4_number) AS total_medals FROM w 
WHERE c2_second = 'usa'
AND c3_minimum_number >= 2006 AND c3_maximum_number <= 2014;
